def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # find sequence rows: rows with a nonzero run then zeros, in first/last rows
    seqs=[]
    for r in (0,h-1):
        row=g[r]; nz=[i for i,v in enumerate(row) if v]
        if nz:
            # contiguous run starting at first nz
            run=[row[i] for i in range(nz[0],nz[-1]+1)]
            if len(run)==len(nz): seqs.append(run)
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v==0: continue
            if r in (0,h-1) and any(v in s for s in seqs) and g[r][max(0,c-1)]==0:
                # part of a sequence row run? skip if this row is a sequence row and cell belongs to run
                continue
            for s in seqs:
                if v in s:
                    start=c-s.index(v)
                    for i,sv in enumerate(s):
                        cc=start+i
                        if 0<=cc<w: out[r][cc]=sv
                    break
    return out
